OPS = {
    '+': operator.add,
    '-': operator.sub,
    '*': operator.mul,
    '/': operator.truediv,
}


def eval_rpn(rpn_tokens):
    """Evaluate a Reverse Polish Notation expression."""
    stack = []

    for tok_type, tok_val in rpn_tokens:
        if tok_type == 'NUM':
            stack.append(tok_val)
        elif tok_type == 'OP':
            if len(stack) < 2:
                raise ValueError("Invalid expression")
            b = stack.pop()
            a = stack.pop()
            op_func = OPS.get(tok_val)
            if op_func is None:
                raise ValueError(f"Unknown operator: {tok_val}")
            if tok_val == '/' and b == 0:
                raise ZeroDivisionError("Division by zero")
            result = op_func(a, b)
            # Convert to int if result is a whole number
            if isinstance(result, float) and result == int(result):
                result = int(result)
            stack.append(result)

    if len(stack) != 1:
        raise ValueError("Invalid expression")

    return stack[0]


# --- High-level evaluate function ---

def evaluate(expr):
    """Evaluate a single expression string and return the result."""
    tokens = tokenize(expr)
    if not tokens:
        return None
    rpn = infix_to_rpn(tokens)
    return eval_rpn(rpn)


# --- CLI ---

def main():
    """Main entry point: read from stdin, evaluate line by line."""
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            result = evaluate(line)
            if result is not None:
                print(result)
        except ZeroDivisionError:
            print("Error: Division by zero")
        except Exception as e:
            print(f"Error: {e}")


